import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { socket } from './socket';
import './DMPage.css';

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [applications, setApplications] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const messagesEndRef = useRef(null);
  const defaultAvatar = '/default-avatar.png';

  const fetchApplications = async () => {
    const token = localStorage.getItem("token"); // Ensure the token is stored

    if (!token) {
      console.error("❌ No token found in localStorage");
      return;
    }

    try {
      const res = await fetch("http://localhost:3000/api/applications", {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`, // ✅ Include the JWT token
        },
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.message);

      console.log("📦 Fetched applications data:", data);
    } catch (error) {
      console.error("❌ Error fetching applications:", error.message);
    }
  };

  useEffect(() => {
    fetchApplications();
  }, []);

  // Fetch chat messages between current user and selected applicant
  const fetchChatMessages = async (applicantId) => {
    try {
      const res = await axios.get(
        `/api/messages?userId=${currentUser._id}&otherUserId=${applicantId}`
      );
      setMessages(res.data);
    } catch (error) {
      console.error('Error fetching chat messages:', error);
    }
  };

  // Handle user authentication and socket connection on mount
  useEffect(() => {
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');
    if (!token || !userData) {
      navigate('/login');
      return;
    }
    socket.auth = { token };
    socket.connect();
    fetchApplications();

    return () => {
      socket.disconnect();
    };
  }, [currentUser, navigate]);

  // Load conversation messages when an applicant is selected
  useEffect(() => {
    if (selectedUser) {
      fetchChatMessages(selectedUser._id);
    }
  }, [selectedUser]);

  // Listen for incoming messages
  useEffect(() => {
    const handleReceiveMessage = (message) => {
      // Add only messages relevant to the currently selected conversation
      if (
        (message.sender === currentUser._id && message.receiver === selectedUser?._id) ||
        (message.receiver === currentUser._id && message.sender === selectedUser?._id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    };

    socket.on('receiveMessage', handleReceiveMessage);
    return () => {
      socket.off('receiveMessage', handleReceiveMessage);
    };
  }, [currentUser, selectedUser]);

  // Send a new chat message
  const handleSend = () => {
    if (!newMessage.trim() || !selectedUser) return;
    const messageData = {
      sender: currentUser._id,
      receiver: selectedUser._id,
      message: newMessage.trim(),
      timestamp: new Date().toISOString(),
    };
    socket.emit('sendMessage', messageData);
    setMessages((prev) => [...prev, messageData]);
    setNewMessage('');
  };

  // Accept an application using an HTTP call to your backend
  const handleAccept = async () => {
    if (!selectedUser) return;
    // Find the matching application (comparing as strings)
    const application = applications.find(
      (app) =>
        app.applicant._id.toString() === selectedUser._id.toString() &&
        app.status === 'pending'
    );
    if (!application) {
      console.error('No pending application found for this user.');
      return;
    }
    try {
      const res = await axios.put('/api/applications/accept', {
        applicantId: application.applicant._id,
        clientId: currentUser._id,
      });
      console.log('Application accepted:', res.data);
      // Update application status locally
      setApplications((prev) =>
        prev.map((app) =>
          app._id === application._id ? { ...app, status: 'accepted' } : app
        )
      );
    } catch (error) {
      console.error('Error accepting application:', error);
    }
  };

  // Render the list of applicants from the applications
  const renderApplicants = () => {
    if (applications.length === 0) return <div className="empty-list">No applications yet</div>;
    return applications.map((app) => {
      const applicant = app.applicant; // assuming populated field from backend
      return (
        <div
          key={app._id}
          className={`applicant-item ${selectedUser && selectedUser._id === applicant._id ? 'active' : ''}`}
          onClick={() => setSelectedUser(applicant)}
        >
          <img
            src={applicant.image || defaultAvatar}
            alt={applicant.name}
            className="user-avatar"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = defaultAvatar;
            }}
          />
          <div className="applicant-info">
            <h3>{applicant.name}</h3>
            <p>{app.message}</p>
          </div>
        </div>
      );
    });
  };

  return (
    <div className="dm-container">
      <div className="dm-sidebar">
        <h2>Applicants</h2>
        {renderApplicants()}
      </div>

      <div className="chat-area">
        {selectedUser ? (
          <>
            <div className="chat-header">
              <img
                src={selectedUser.image || defaultAvatar}
                alt={selectedUser.name}
                className="user-avatar"
                onError={(e) => {
                  e.target.onerror = null;
                  e.target.src = defaultAvatar;
                }}
              />
              <h3>{selectedUser.name}</h3>
              <button onClick={handleAccept} className="accept-btn">
                Accept Client
              </button>
            </div>

            <div className="messages-container">
              {messages.map((msg, index) => (
                <div
                  key={msg._id || index}
                  className={`message ${msg.sender === currentUser._id ? 'sent' : 'received'}`}
                >
                  <p>{msg.message}</p>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <div className="message-input">
              <input
                type="text"
                placeholder="Type a message..."
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
              />
              <button onClick={handleSend} disabled={!newMessage.trim()}>
                Send
              </button>
            </div>
          </>
        ) : (
          <div className="empty-chat">Select an applicant to start chatting</div>
        )}
      </div>
    </div>
  );
};

export default DMPage;
